package vn.edu.ltweb.jwtmvc.api; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import vn.edu.ltweb.jwtmvc.user.DuplicateEmailException;
@RestControllerAdvice public class RestExceptionHandler { @ExceptionHandler({DuplicateEmailException.class,org.springframework.web.bind.MethodArgumentNotValidException.class}) ResponseEntity<ApiError> bad(Exception e){return ResponseEntity.badRequest().body(new ApiError(400,"BAD_REQUEST",e.getMessage()));}}
